package com.bank.lb;

import com.bank.lb.gen.*;
import io.grpc.stub.StreamObserver;
import java.math.BigDecimal;
import java.util.Map;
import java.util.logging.Logger;

public class AccountServiceImpl extends AccountServiceGrpc.AccountServiceImplBase {
    private static final Logger log = Logger.getLogger(AccountServiceImpl.class.getName());
    private final String instanceId;
    private final Map<String, BigDecimal> balances = Map.of(
        "SAV2001", new BigDecimal("1000000"),   // Rajesh
        "CUR3001", new BigDecimal("250000"));    // Priya

    AccountServiceImpl(String instanceId) { this.instanceId = instanceId; }

    @Override
    public void getBalance(BalanceRequest req, StreamObserver<BalanceResponse> obs) {
        log.info(() -> "[" + instanceId + "] GetBalance " + req.getAccountId());
        obs.onNext(BalanceResponse.newBuilder()
            .setAccountId(req.getAccountId())
            .setBalance(balances.getOrDefault(req.getAccountId(), BigDecimal.ZERO).toString())
            .setServedBy(instanceId)
            .build());
        obs.onCompleted();
    }
}
