package com.bank.lb;

import io.grpc.Server;
import io.grpc.ServerBuilder;
import java.util.logging.Logger;

// Start several of these on different ports to SIMULATE multiple pods.
public class GrpcServer {
    private static final Logger log = Logger.getLogger(GrpcServer.class.getName());
    public static void main(String[] args) throws Exception {
        int port = Integer.parseInt(args[0]);
        String id = "pod-" + port;
        Server server = ServerBuilder.forPort(port)
            .addService(new AccountServiceImpl(id)).build().start();
        log.info("Account service " + id + " on " + port);
        server.awaitTermination();
    }
}
