package com.bank.lb;

import com.bank.lb.gen.*;
import io.grpc.ManagedChannel;
import io.grpc.ManagedChannelBuilder;
import java.util.logging.Logger;

public class BalancedClient {
    private static final Logger log = Logger.getLogger(BalancedClient.class.getName());

    public static void main(String[] args) {
        // CLIENT-SIDE load balancing: resolver returns MANY backends, round_robin rotates.
        // In K8s use dns:///account-service.default.svc:9090 backed by a HEADLESS service
        // so DNS returns ALL pod IPs (a ClusterIP would return ONE and re-pin the problem).
        ManagedChannel channel = ManagedChannelBuilder
            .forTarget("dns:///localhost:9091,localhost:9092,localhost:9093")
            .defaultLoadBalancingPolicy("round_robin")   // or "pick_first"
            .usePlaintext()
            .build();

        AccountServiceGrpc.AccountServiceBlockingStub stub =
            AccountServiceGrpc.newBlockingStub(channel);

        // 6 calls should spread across the 3 backends (pod-9091, pod-9092, pod-9093)
        for (int i = 0; i < 6; i++) {
            BalanceResponse r = stub.getBalance(
                BalanceRequest.newBuilder().setAccountId("SAV2001").build());
            log.info(() -> "served_by=" + r.getServedBy() + " balance=Rs." + r.getBalance());
        }
        channel.shutdown();
    }
}
